:root {
  --ink: #202235;
  --paper: #fffdf5;
  --blue: #536dff;
  --lime: #d9f75b;
  --line: #c9c9d4;
  --muted: #6b6d7d;
}

* {
  box-sizing: border-box;
}

.patch-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.patch-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wave {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--paper);
  background: var(--blue);
  border-radius: 10px;
  font-size: 23px;
  font-weight: 700;
  line-height: 1;
}

.eyebrow,
.control-value,
.slot {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.patch-title {
  margin: 2px 0 0;
  font-size: 20px;
  line-height: 1.05;
  letter-spacing: -0.4px;
}

.status {
  padding: 5px 8px;
  color: var(--ink);
  background: var(--lime);
  border: 1px solid var(--ink);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
  margin: 0;
  padding: 12px 16px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.dial-card {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 8px;
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 11px;
}

.dial {
  display: grid;
  flex: 0 0 39px;
  width: 39px;
  height: 39px;
  place-items: center;
  background: var(--lime);
  border: 2px solid var(--ink);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.control-name {
  display: block;
  font-size: 12px;
  line-height: 1.1;
}

.control-value {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
  white-space: nowrap;
}

.patch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
}

.slot {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.6px;
}

button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}
